import {
  DataGridPremium,
  DataGridPremiumProps,
  GridColDef,
  GridPivotModel,
  GridSidebarValue,
} from '@mui/x-data-grid-premium';

const getPivotDerivedColumns: DataGridPremiumProps['getPivotDerivedColumns'] = (
  column,
) => {
  if (column.type === 'date') {
    const field = column.field;
    return [
      {
        field: `${field}-year`,
        headerName: `${column.headerName} (Year)`,
        valueGetter: (_, row) => new Date(row[field]).getFullYear(),
      },

      {
        field: `${field}-month`,
        headerName: `${column.headerName} (Month)`,
        type: 'number',
        valueGetter: (_, row) => new Date(row[field]).getMonth(),
        valueFormatter: (month) =>
          new Date(0, month).toLocaleString(undefined, { month: 'long' }),
      },
    ];
  }
  return undefined;
};
const getYearField = (field: string) => `${field}-year`;
const getMonthField = (field: string) => `${field}-month`;

const columns: GridColDef[] = [
  { field: 'id', headerName: 'ID', width: 90 },
  {
    field: 'transactionDate',
    type: 'date',
    headerName: 'Transaction Date',
    width: 140,
    valueGetter: (value) => (value ? new Date(value) : null),
  },
  { field: 'ticker', headerName: 'Ticker', rowHeader: true },
  {
    field: 'price',
    type: 'number',
    headerName: 'Price',
    valueFormatter: (value: number | undefined) =>
      value ? `$${value.toFixed(2)}` : null,
  },
  { field: 'volume', type: 'number', headerName: 'Volume' },
  {
    field: 'type',
    type: 'singleSelect',
    valueOptions: ['stock', 'bond'],
    headerName: 'Type',
  },
];

